Tr.Begin();
for (int i = 3; i >= 1; i--)
{
    Tr.At(1, "سطر جديد: الحلقة الداخلية ستطبع i نجوم.", "i", i);
    for (int j = 1; j <= i; j++)
    { //~
        Console.Write("*");
        Tr.S("نجمة في السطر نفسه.", "j", j);
    } //~
    Tr.Drop("j");
    Console.WriteLine();
    Tr.S("انتهى السطر: ننزل سطرًا جديدًا.");
}
Tr.Drop("i");
Tr.End();

Tr.Begin();
int count = 0;
Tr.S("العدّاد يبدأ من صفر.", "count", count);
for (int i = 1; i <= 12; i++)
{ //~
    Tr.At(3, 12 % i == 0 ? "الباقي صفر: i يقسم 12." : "الباقي ليس صفرًا: i لا يقسم 12.", "i", i, "12 % i", 12 % i);
    if (12 % i == 0)
    { //~
        count++;
        Tr.S("نزيد العدّاد.", "count", count);
    } //~
} //~
Tr.Drop("i");
Console.WriteLine(count);
Tr.S("الطباعة: 6 قواسم.");
Tr.End();
